/**
 * BugSleuth frontend — handles form submission, demo loading, and report rendering.
 * Uses the Fetch API; no external dependencies required.
 */

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

document.addEventListener("DOMContentLoaded", () => {
  document.getElementById("btn-investigate").addEventListener("click", runInvestigation);
  document.getElementById("btn-demo").addEventListener("click", runDemo);
});

// ---------------------------------------------------------------------------
// API calls
// ---------------------------------------------------------------------------

async function runDemo() {
  showSpinner();
  try {
    const res = await fetch("/demo");
    const data = await res.json();
    if (data.error) throw new Error(data.error);
    renderReport(data);
  } catch (err) {
    showError(err.message);
  }
}

async function runInvestigation() {
  showSpinner();

  const formData = new FormData();
  formData.append("description", val("description"));
  formData.append("log_text",    val("log_text"));
  formData.append("code_text",   val("code_text"));
  formData.append("change_text", val("change_text"));

  const logFile  = document.getElementById("log_file").files[0];
  const codeZip  = document.getElementById("code_zip").files[0];
  if (logFile)  formData.append("log_file", logFile);
  if (codeZip)  formData.append("code_zip", codeZip);

  try {
    const res = await fetch("/investigate", { method: "POST", body: formData });
    const data = await res.json();
    if (data.error) throw new Error(data.error);
    renderReport(data);
  } catch (err) {
    showError(err.message);
  }
}

// ---------------------------------------------------------------------------
// Report rendering
// ---------------------------------------------------------------------------

function renderReport(d) {
  const panel = document.getElementById("report");
  panel.innerHTML = `
    ${renderPipeline()}
    ${renderIncidentHeader(d)}
    ${renderEvidenceGrid(d.findings)}
    ${renderTribunal(d.prosecution, d.defense)}
    ${renderVerdict(d.verdict)}
    ${renderActions(d.verdict.recommended_actions)}
    <p class="run-id">Run ID: ${d.run_id} &nbsp;·&nbsp; ${d.started_at}</p>
  `;
}

function renderPipeline() {
  const steps = ["Incident", "Evidence", "Tribunal", "Verdict", "Proof"];
  const items = steps.map(s => `<div class="step done">${s}</div>`).join("");
  return `<div class="pipeline">${items}</div>`;
}

function renderIncidentHeader(d) {
  return `
    <div class="card">
      <div class="card-title">Incident</div>
      <p>${esc(d.incident_description)}</p>
      <p style="margin-top:8px;font-size:12px;color:#64748b">
        ${d.synthesis.investigator_count} investigators · 
        avg confidence ${pct(d.synthesis.average_investigator_confidence)} · 
        tags: ${d.synthesis.all_tags.join(", ")}
      </p>
    </div>`;
}

function renderEvidenceGrid(findings) {
  if (!findings || !findings.length) return "";
  const cards = findings.map(f => `
    <div class="evidence-card">
      <div class="eid">${esc(f.evidence_id)}</div>
      <div class="source">${esc(f.source.replace("_", " "))}</div>
      <div class="finding">${esc(f.finding)}</div>
      <div class="conf-bar">
        <div class="conf-fill" style="width:${pct(f.confidence)}"></div>
      </div>
      <div style="font-size:11px;color:#475569;margin-top:4px">confidence ${pct(f.confidence)}</div>
    </div>`).join("");
  return `
    <div class="card">
      <div class="card-title">Evidence</div>
      <div class="evidence-grid">${cards}</div>
    </div>`;
}

function renderTribunal(prosecution, defense) {
  return `
    <div class="card">
      <div class="card-title">Tribunal</div>
      <div class="tribunal-grid">
        <div>
          <div class="role-label role-prosecutor">⚖ Prosecutor</div>
          <p style="font-size:13px;margin-bottom:6px"><strong>${esc(prosecution.hypothesis)}</strong></p>
          <p style="font-size:12px;color:#94a3b8">${esc(prosecution.argument)}</p>
          <p style="font-size:11px;color:#7c3aed;margin-top:6px">
            Evidence: ${prosecution.evidence_ids.join(", ")} · confidence ${pct(prosecution.confidence)}
          </p>
        </div>
        <div class="tribunal-divider"></div>
        <div>
          <div class="role-label role-defense">🛡 Defense</div>
          <p style="font-size:13px;margin-bottom:6px"><strong>${esc(defense.challenge)}</strong></p>
          <p style="font-size:12px;color:#94a3b8">${esc(defense.argument)}</p>
          <ul style="margin-top:8px;padding-left:16px;font-size:11px;color:#64748b">
            ${(defense.weaknesses || []).map(w => `<li>${esc(w)}</li>`).join("")}
          </ul>
        </div>
      </div>
    </div>`;
}

function renderVerdict(verdict) {
  const cls = `verdict-${verdict.status}`;
  return `
    <div class="card">
      <div class="card-title">Verdict</div>
      <div class="verdict-badge ${cls}">${verdict.status.replace(/_/g, " ")}</div>
      <p style="font-weight:600;margin-bottom:8px">${esc(verdict.root_cause)}</p>
      <p style="font-size:13px;color:#94a3b8">${esc(verdict.reasoning)}</p>
      <p style="font-size:12px;color:#475569;margin-top:8px">
        Net confidence: ${pct(verdict.confidence)} 
        (prosecution ${pct(verdict.prosecution_weight)} − defense reduction ${pct(verdict.defense_weight)})
        · Evidence cited: ${verdict.evidence_ids.join(", ")}
      </p>
    </div>`;
}

function renderActions(actions) {
  if (!actions || !actions.length) return "";
  const items = actions.map(a => `<li>${esc(a)}</li>`).join("");
  return `
    <div class="card">
      <div class="card-title">Recommended Actions</div>
      <ul class="actions-list">${items}</ul>
    </div>`;
}

// ---------------------------------------------------------------------------
// UI helpers
// ---------------------------------------------------------------------------

function showSpinner() {
  const panel = document.getElementById("report");
  panel.innerHTML = `
    <div id="spinner" class="active">
      <div class="spin-ring"></div>
      <span style="color:#64748b;font-size:13px">Running investigation…</span>
    </div>`;
  setButtons(true);
}

function showError(msg) {
  document.getElementById("report").innerHTML = `
    <div class="card" style="border-color:#7f1d1d">
      <div class="card-title" style="color:#f87171">Error</div>
      <p style="color:#fca5a5">${esc(msg)}</p>
    </div>`;
  setButtons(false);
}

function setButtons(disabled) {
  document.getElementById("btn-investigate").disabled = disabled;
  document.getElementById("btn-demo").disabled = disabled;
}

// Re-enable buttons after render
function renderReport_wrap(d) {
  renderReport(d);
  setButtons(false);
}

// Patch renderReport to always re-enable buttons
const _orig = renderReport;
window.renderReport = function(d) { _orig(d); setButtons(false); };

// Escape HTML to prevent XSS from evidence content
function esc(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function val(id) {
  return (document.getElementById(id) || {}).value || "";
}

function pct(n) {
  return Math.round((n || 0) * 100) + "%";
}

