"""Abstract base class for all BugSleuth investigators."""

from abc import ABC, abstractmethod


class Investigator(ABC):
    @abstractmethod
    def investigate(self, incident: dict) -> dict:
        """Run investigation and return a structured result dict."""

"""
Pipeline Investigator — scans for CI/CD configuration files (GitHub Actions,
GitLab CI, Jenkins, CircleCI, etc.) and reports what was found.
"""

from pathlib import Path
from .base import Investigator

_PIPELINE_FILES = {
    ".github/workflows": "GitHub Actions",
    ".gitlab-ci.yml": "GitLab CI",
    "Jenkinsfile": "Jenkins",
    ".circleci/config.yml": "CircleCI",
    "azure-pipelines.yml": "Azure Pipelines",
    "bitbucket-pipelines.yml": "Bitbucket Pipelines",
    ".travis.yml": "Travis CI",
}


class PipelineInvestigator(Investigator):
    def __init__(self, source_path: Path):
        self.source_path = Path(source_path)

    def investigate(self, incident: dict) -> dict:
        findings = []
        evidence = []
        pipeline_detected = False
        pipeline_type = None

        for rel, name in _PIPELINE_FILES.items():
            candidate = self.source_path / rel
            if candidate.exists():
                pipeline_detected = True
                pipeline_type = name
                findings.append(f"{name} pipeline configuration detected.")

                # Collect workflow files for evidence
                if candidate.is_dir():
                    for yml in candidate.glob("*.yml"):
                        evidence.append(str(yml.relative_to(self.source_path)))
                        _scan_workflow(yml, findings, evidence)
                else:
                    evidence.append(rel)

        if not pipeline_detected:
            findings.append("No CI/CD pipeline configuration files were found.")
            return {
                "agent": "Pipeline Investigator",
                "status": "complete",
                "findings": findings,
                "evidence": evidence,
                "confidence": 0.10,
                "pipeline_detected": False,
                "pipeline_type": None,
            }

        return {
            "agent": "Pipeline Investigator",
            "status": "complete",
            "findings": findings,
            "evidence": evidence,
            "confidence": 0.65,
            "pipeline_detected": True,
            "pipeline_type": pipeline_type,
        }


def _scan_workflow(path: Path, findings: list, evidence: list) -> None:
    """Extract test/deploy steps from a workflow YAML file."""
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return

    evidence.append(f"{path.name}: workflow file found")
    lines = text.splitlines()
    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if stripped.startswith("- run:") or stripped.startswith("run:"):
            evidence.append(f"{path.name}:{i}: {stripped}")
        if any(kw in stripped.lower() for kw in ("pytest", "test", "deploy", "publish")):
            findings.append(f"Step found in {path.name}: {stripped[:80]}")

"""
Deployment Context Investigator — detects containerization (Docker),
orchestration (Kubernetes, Compose), and infrastructure-as-code files.
"""

from pathlib import Path
from .base import Investigator

_CONTAINER_INDICATORS = ["Dockerfile", "dockerfile", ".dockerignore"]
_COMPOSE_INDICATORS   = ["docker-compose.yml", "docker-compose.yaml", "compose.yml", "compose.yaml"]
_K8S_INDICATORS       = ["k8s", "kubernetes", "manifests", "helm"]
_K8S_API_VERSIONS     = ["apiVersion: apps/v1", "kind: Deployment", "kind: Service", "kind: Pod"]
_TERRAFORM_INDICATORS = [".tf", ".tfvars"]
_ANSIBLE_INDICATORS   = ["playbook.yml", "ansible.cfg", "inventory"]


class DeploymentContextInvestigator(Investigator):
    def __init__(self, source_path: Path):
        self.source_path = Path(source_path)

    def investigate(self, incident: dict) -> dict:
        findings = []
        evidence = []
        profile = {
            "containerization": "Not detected",
            "orchestration": "Not detected",
            "infrastructure_as_code": "Not detected",
        }

        self._check_docker(profile, findings, evidence)
        self._check_kubernetes(profile, findings, evidence)
        self._check_iac(profile, findings, evidence)

        if not findings:
            findings.append("No deployment configuration files were detected.")

        return {
            "agent": "Deployment Context Investigator",
            "status": "complete",
            "findings": findings,
            "evidence": evidence,
            "confidence": 0.55 if any(v != "Not detected" for v in profile.values()) else 0.10,
            "deployment_profile": profile,
        }

    def _check_docker(self, profile: dict, findings: list, evidence: list) -> None:
        for name in _CONTAINER_INDICATORS:
            p = self.source_path / name
            if p.exists():
                profile["containerization"] = "Dockerfile detected"
                findings.append(f"Docker configuration found: {name}")
                evidence.append(name)

        for name in _COMPOSE_INDICATORS:
            p = self.source_path / name
            if p.exists():
                findings.append(f"Docker Compose configuration found: {name}")
                evidence.append(name)
                try:
                    text = p.read_text(encoding="utf-8")
                    for line in text.splitlines():
                        if any(kw in line.lower() for kw in ("image:", "ports:", "environment:")):
                            evidence.append(f"{name}: {line.strip()}")
                except OSError:
                    pass

    def _check_kubernetes(self, profile: dict, findings: list, evidence: list) -> None:
        # Check for k8s directories
        for name in _K8S_INDICATORS:
            d = self.source_path / name
            if d.is_dir():
                profile["orchestration"] = "Kubernetes manifests detected"
                findings.append(f"Kubernetes manifests directory found: {name}/")
                # Scan YAML files for replica count and resource kind
                for yml in d.rglob("*.yaml"):
                    try:
                        text = yml.read_text(encoding="utf-8")
                        evidence.append(str(yml.relative_to(self.source_path)))
                        for line in text.splitlines():
                            if "replicas" in line.lower():
                                findings.append(f"Replica configuration: {line.strip()}")
                                evidence.append(f"{yml.name}: {line.strip()}")
                            if any(k in line for k in _K8S_API_VERSIONS):
                                evidence.append(f"{yml.name}: {line.strip()}")
                    except OSError:
                        pass
                break

        # Check for loose YAML files with Kubernetes API versions
        if profile["orchestration"] == "Not detected":
            for yml in self.source_path.glob("*.yaml"):
                try:
                    text = yml.read_text(encoding="utf-8")
                    if any(k in text for k in _K8S_API_VERSIONS):
                        profile["orchestration"] = "Kubernetes detected"
                        findings.append(f"Kubernetes manifest found: {yml.name}")
                        evidence.append(yml.name)
                except OSError:
                    pass

    def _check_iac(self, profile: dict, findings: list, evidence: list) -> None:
        tf_files = list(self.source_path.rglob("*.tf"))
        if tf_files:
            profile["infrastructure_as_code"] = "Terraform detected"
            findings.append(f"Terraform configuration found ({len(tf_files)} .tf file(s))")
            evidence.extend(str(f.relative_to(self.source_path)) for f in tf_files[:3])

